import { chromium } from '@playwright/test'

const BASE = process.env.BASE ?? 'http://127.0.0.1:3100'
const VIEWPORT = { width: 1440, height: 900 }

const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: VIEWPORT })
const page = await ctx.newPage()

const started = new Map()
const finished = []
page.on('request', (r) => {
  if (r.url().includes('/_next/image')) started.set(r.url(), Date.now())
})
page.on('requestfinished', (r) => {
  if (r.url().includes('/_next/image')) {
    finished.push({ url: r.url(), ms: Date.now() - started.get(r.url()) })
  }
})
page.on('requestfailed', (r) => {
  if (r.url().includes('/_next/image')) {
    finished.push({ url: r.url(), ms: Date.now() - started.get(r.url()), failed: true })
  }
})

const t0 = Date.now()
await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
const domReady = Date.now() - t0
console.log(`viewport ${VIEWPORT.width}x${VIEWPORT.height}, cold optimiser cache`)
console.log(`DOMContentLoaded: ${domReady}ms`)

// How many optimiser jobs does the browser start without any scrolling?
for (const wait of [1000, 3000, 5000]) {
  await page.waitForTimeout(wait - (Date.now() - t0 - domReady) > 0 ? 200 : 200)
  await page.waitForTimeout(200)
}
await page.waitForTimeout(3000)
console.log(`\noptimiser requests started (no scroll): ${started.size}`)
console.log(`  completed: ${finished.length}, still pending: ${started.size - finished.length}`)
if (finished.length) {
  const times = finished.map((f) => f.ms).sort((a, b) => a - b)
  console.log(`  per-request ms: min ${times[0]}, median ${times[Math.floor(times.length / 2)]}, max ${times[times.length - 1]}`)
}

// The #230 reproduction: issue an unrelated navigation while jobs are in flight.
const beforeNav = started.size - finished.length
const navStart = Date.now()
let navError = null
try {
  await page.goto(`${BASE}/login`, { waitUntil: 'domcontentloaded', timeout: 30000 })
} catch (e) {
  navError = e.message.split('\n')[0]
}
console.log(`\nsecond navigation to /login issued with ${beforeNav} optimiser jobs pending`)
console.log(`  result: ${navError ?? 'ok'} in ${Date.now() - navStart}ms`)

await browser.close()

