/**
 * Does `content-visibility: auto` on each category section stop Chrome
 * speculatively fetching the images inside the off-screen ones?
 *
 * Injected at document-start so the rule is in force before the browser makes
 * any loading decision -- applying it after load would measure nothing.
 */
import { chromium } from '@playwright/test'

const BASE = 'http://127.0.0.1:3100'
const VIEWPORT = { width: 1440, height: 900 }

// Each category renders as a Block whose outer element is a direct child of
// <body>. Target those, skipping the hero (first) and header.
const CSS = `
  body > div:nth-of-type(n+2) {
    content-visibility: auto;
    contain-intrinsic-size: auto 1200px;
  }
`

async function run(label, { injectCss }) {
  const browser = await chromium.launch()
  const ctx = await browser.newContext({ viewport: VIEWPORT })
  if (injectCss) {
    await ctx.addInitScript((css) => {
      document.addEventListener('DOMContentLoaded', () => {}, { once: true })
      const style = document.createElement('style')
      style.textContent = css
      const attach = () => (document.head || document.documentElement).appendChild(style)
      if (document.head) attach()
      else new MutationObserver((_, o) => { if (document.head) { attach(); o.disconnect() } })
        .observe(document.documentElement, { childList: true, subtree: true })
    }, CSS)
  }
  const page = await ctx.newPage()
  const reqs = new Set()
  page.on('request', (r) => { if (r.url().includes('/_next/image')) reqs.add(r.url()) })

  await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(2500)
  const imgCount = await page.locator('img').count()
  const applied = await page.evaluate(() => {
    const el = document.querySelectorAll('body > div')[1]
    return el ? getComputedStyle(el).contentVisibility : 'no-element'
  })
  console.log(`${label.padEnd(28)} imgs in DOM: ${imgCount}  optimiser requests: ${reqs.size}   (content-visibility on section 2: ${applied})`)
  await browser.close()
  return reqs.size
}

const base = await run('baseline (no CSS)', { injectCss: false })
const withCv = await run('content-visibility: auto', { injectCss: true })
console.log(`\nrequests ${base} -> ${withCv}`)

